from pathlib import Path

SOURCE = Path('index.html')
OUTPUT = Path('index_integrated.html')

s = SOURCE.read_text(encoding='utf-8')

css = '''
.market-refresh{margin:-4px 0 13px;padding:9px 12px;border:1px solid rgba(255,255,255,.08);border-radius:11px;background:rgba(255,255,255,.035);color:#8e97af;font-size:9px;line-height:1.55}
.market-metric strong small{display:block;margin-top:5px;color:#9ca4bb;font-size:9px;font-weight:600}.market-table td small{color:#778199}.market-tick .prior-label{color:#747e96;font-size:8px}
'''
s = s.replace('</style>', css + '</style>', 1)

refresh_html = '<div class="market-refresh" id="marketLastUpdated">Latest market data update: loading...</div>'
needle = '<div class="market-note-dark">Market snapshot compiled from dated public sources. Values are delayed and unavailable comparable fields remain N/A.</div>'
if needle not in s:
    raise RuntimeError('Capital-market note was not found in index.html')
s = s.replace(needle, needle + refresh_html, 1)

start = s.index('function renderMarket(sel){')
end = s.index('function render(){', start)

new_func = r'''function renderMarket(sel){let latest=marketLatest(),m=latest.find(x=>x.company===sel),currency=m?.currency||'',price=m?num(m.price):null,cap=m?num(m.market_cap):null,pev=m?num(m.pe):null,pbv=m?num(m.pb):null,ytd=m?num(m.ytd_return):null,colors={Aumovio:'#ff4208',Luxshare:'#2563eb',HASCO:'#14b8a6',Tuopu:'#8b5cf6',Baolong:'#f59e0b',BTL:'#ef4444',NASN:'#64748b'};let rate=Number(localStorage.getItem('eurCnyRate'))||8.35;eurCnyRate.value=rate.toFixed(2);applyFx.onclick=()=>{let v=Number(eurCnyRate.value);if(Number.isFinite(v)&&v>0){localStorage.setItem('eurCnyRate',v);renderMarket(sel)}};let capCny=x=>{let v=num(x.market_cap);return Number.isFinite(v)&&String(x.currency).toUpperCase()==='EUR'?v*rate:v},priceCny=x=>{let v=num(x.price);return Number.isFinite(v)&&String(x.currency).toUpperCase()==='EUR'?v*rate:v},fmtPrice=x=>Number.isFinite(num(x.price))?`${num(x.price).toFixed(2)} ${x.currency||''}`:'N/A',fmtPriceDual=x=>{let p=num(x.price);if(!Number.isFinite(p))return'N/A';let original=`${p.toFixed(2)} ${x.currency||''}`;return String(x.currency).toUpperCase()==='EUR'?`${original}<br><small>≈ ${priceCny(x).toFixed(2)} CNY</small>`:original},fmtCap=x=>Number.isFinite(num(x.market_cap))?`${bn(num(x.market_cap))} ${x.currency||''}`:'N/A',fmtV=v=>Number.isFinite(num(v))?`${num(v).toFixed(1)}x`:'N/A',companyHist=c=>marketHistory.filter(x=>canon(x.company)===c&&Number.isFinite(num(x.price))).sort((a,b)=>String(a.date).localeCompare(String(b.date))),dayMove=c=>{let a=companyHist(c);if(a.length<2)return null;let p=num(a.at(-1).price),q=num(a.at(-2).price);return Number.isFinite(p)&&Number.isFinite(q)&&q!==0?p/q-1:null};sharePrice.innerHTML=m?fmtPriceDual(m):'N/A';marketCap.innerHTML=Number.isFinite(cap)?`${bn(cap)} ${currency}${String(currency).toUpperCase()==='EUR'?`<br><small>≈ ${bn(cap*rate)} CNY</small>`:''}`:'N/A';peRatio.textContent=Number.isFinite(pev)?`${pev.toFixed(1)}x`:'N/A';pbRatio.textContent=Number.isFinite(pbv)?`${pbv.toFixed(1)}x`:'N/A';marketYtd.textContent=Number.isFinite(ytd)?pct(ytd):'N/A';marketSubtitle.textContent=m?`${m.date} latest public observation · ${m.ticker||sel}`:'No market record for selected company';let latestDate=[...new Set(latest.map(x=>String(x.date||'')).filter(Boolean))].sort().at(-1)||'N/A',refresh=document.getElementById('marketLastUpdated');if(refresh){refresh.textContent=`Latest market-data snapshot: ${latestDate} · Checking file update time...`;fetch(PATH.market,{method:'HEAD',cache:'no-store'}).then(r=>{let lm=r.headers.get('last-modified');if(!lm)throw Error('No Last-Modified header');let t=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(lm));refresh.textContent=`Latest market data update: ${t} (Shanghai time) · Latest trading-date snapshot: ${latestDate}`}).catch(()=>{refresh.textContent=`Latest trading-date snapshot: ${latestDate} · Exact update time is unavailable from the published CSV headers.`})}let tickerRows=latest.filter(x=>Number.isFinite(num(x.price))),tickerLoop=[...tickerRows,...tickerRows];marketTicker.innerHTML=tickerLoop.map(x=>{let r=dayMove(x.company),cl=Number.isFinite(r)&&r<0?'market-down':'market-up',arrow=Number.isFinite(r)?(r<0?'▼':'▲'):'';return`<div class="market-tick"><b>${x.company==='Aumovio'?'AUMOVIO':x.company}</b><span>${fmtPrice(x)}${String(x.currency).toUpperCase()==='EUR'?` · ≈ ${priceCny(x).toFixed(2)} CNY`:''}</span><span class="${cl}">${Number.isFinite(r)?`${arrow} ${Math.abs(r*100).toFixed(2)}%`: 'N/A'} <span class="prior-label">vs prior close</span></span></div>`}).join('');marketPeerRows.innerHTML=[...latest].sort((a,b)=>(capCny(b)||-Infinity)-(capCny(a)||-Infinity)).map(x=>{let r=num(x.ytd_return),cl=Number.isFinite(r)&&r<0?'market-down':'market-up',name=x.company==='Aumovio'?'AUMOVIO':x.company,color=colors[x.company]||'#64748b',converted=String(x.currency).toUpperCase()==='EUR'&&Number.isFinite(capCny(x))?`<br><small>≈ ${bn(capCny(x))} CNY</small>`:'';return`<tr><td><div class="market-company"><span class="market-logo" style="background:${color}">${name.slice(0,2).toUpperCase()}</span><span><b>${name}</b><br><small>${x.ticker||''}</small></span></div></td><td>${fmtPriceDual(x)}</td><td>${fmtCap(x)}${converted}</td><td>${fmtV(x.pe)}</td><td>${fmtV(x.pb)}</td><td class="${cl}">${Number.isFinite(r)?pct(r):'N/A'}</td></tr>`}).join('');let hist=marketHistory.filter(x=>Number.isFinite(num(x.price))),dates=[...new Set(hist.map(x=>String(x.date)))].sort(),companies=[...new Set(hist.map(x=>canon(x.company)))];reset('marketTrend');charts.marketTrend=new Chart(marketTrendChart,{type:'line',data:{labels:dates,datasets:companies.map(c=>{let rows=hist.filter(x=>canon(x.company)===c),cur=rows.find(x=>x.currency)?.currency||latest.find(x=>x.company===c)?.currency||'',map=Object.fromEntries(rows.map(x=>[String(x.date),num(x.price)])),color=colors[c]||'#64748b';return{label:c==='Aumovio'?'AUMOVIO':c,data:dates.map(d=>map[d]??null),currency:cur,borderColor:color,backgroundColor:'transparent',borderWidth:c===sel?3:1.7,pointRadius:c===sel?2:1,tension:.25,spanGaps:true}})},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{position:'top',labels:{color:'#9ca4bb',usePointStyle:true,boxWidth:8}},datalabels:{display:false},tooltip:{backgroundColor:'#111522',callbacks:{label:c=>`${c.dataset.label}: ${Number(c.raw).toFixed(2)} ${c.dataset.currency}`}}},scales:{x:{ticks:{color:'#8e97af',maxTicksLimit:12},grid:{display:false}},y:{ticks:{color:'#8e97af'},grid:{color:'rgba(255,255,255,.06)'},title:{display:true,text:'Local-currency closing price',color:'#8e97af'}}}}});let peRows=latest.filter(x=>Number.isFinite(num(x.pe))),ytdRows=latest.filter(x=>Number.isFinite(num(x.ytd_return))),best=[...ytdRows].sort((a,b)=>num(b.ytd_return)-num(a.ytd_return))[0],low=[...peRows].sort((a,b)=>num(a.pe)-num(b.pe))[0],growth=[...data].filter(x=>Number.isFinite(x.revenueGrowth)).sort((a,b)=>b.revenueGrowth-a.revenueGrowth)[0],med=median(peRows.map(x=>num(x.pe))),sig=[];if(best)sig.push({c:'#3ddc97',t:`${best.company==='Aumovio'?'AUMOVIO':best.company} momentum lead`,v:pct(num(best.ytd_return)),p:'Highest YTD share-price return in the loaded peer snapshot.'});if(growth)sig.push({c:'#55a7ff',t:`${growth.company==='Aumovio'?'AUMOVIO':growth.company} financial growth signal`,v:pct(growth.revenueGrowth),p:'Highest revenue growth in the selected financial period.'});if(low)sig.push({c:'#ffbd5a',t:`${low.company==='Aumovio'?'AUMOVIO':low.company} valuation signal`,v:fmtV(low.pe),p:Number.isFinite(med)?`P/E is below the loaded peer median of ${med.toFixed(1)}x.`:'Lowest available P/E.'});sig.push({c:'#ff7a50',t:'FX comparison basis',v:`1 EUR = ${rate.toFixed(2)} CNY`,p:'AUMOVIO share price and market cap show CNY equivalents while retaining original EUR values.'});marketSignals.innerHTML=sig.map(x=>`<div class="market-signal" style="--sig:${x.c}"><div><b>${x.t}</b><em>${x.v}</em></div><p>${x.p}</p></div>`).join('');let revMap=Object.fromEntries(data.map(x=>[x.company,x.revenue])),v=latest.filter(x=>Number.isFinite(num(x.pe))&&Number.isFinite(capCny(x)));reset('valuation');charts.valuation=new Chart(valuationChart,{type:'bubble',data:{datasets:v.map(x=>{let rev=revMap[x.company],r=Number.isFinite(rev)?Math.max(7,Math.min(25,Math.sqrt(rev/1e9)*2.3)):8,color=colors[x.company]||'#64748b';return{label:x.company==='Aumovio'?'AUMOVIO':x.company,meta:x,data:[{x:capCny(x)/1e9,y:num(x.pe),r}],backgroundColor:color+'cc',borderColor:color,borderWidth:x.company===sel?3:1.5}})},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top',labels:{color:'#9ca4bb',usePointStyle:true,boxWidth:8}},datalabels:{display:false},tooltip:{backgroundColor:'#111522',callbacks:{title:i=>i[0].dataset.label,label:c=>{let x=c.dataset.meta,rev=revMap[x.company];return[`Original Share Price: ${fmtPrice(x)}`,`Share Price in CNY: ${priceCny(x).toFixed(2)} CNY`,`Original Market Cap: ${fmtCap(x)}`,`Market Cap for chart: ${bn(capCny(x))} CNY`,`FX rate: ${String(x.currency).toUpperCase()==='EUR'?rate.toFixed(2):'1.00'}`,`P/E: ${fmtV(x.pe)}`,`P/B: ${fmtV(x.pb)}`,`Revenue: ${Number.isFinite(rev)?bn(rev):'N/A'}`]}}}},scales:{x:{title:{display:true,text:'Market Cap (CNY bn)',color:'#8e97af'},ticks:{color:'#8e97af'},grid:{color:'rgba(255,255,255,.06)'}},y:{title:{display:true,text:'P/E (x)',color:'#8e97af'},ticks:{color:'#8e97af'},grid:{color:'rgba(255,255,255,.06)'}}}}})}
'''

s = s[:start] + new_func + s[end:]
OUTPUT.write_text(s, encoding='utf-8')
print(f'Created {OUTPUT} ({OUTPUT.stat().st_size} bytes)')
